def compute(vars):
    current = vars["v1"]
    previous = vars["v2"]

    if previous == 0:
        return None

    change = current - previous
    change_ratio = change / previous * 100

    return {
        "value": change_ratio,
        "trace": {
            "current_value": current,
            "previous_value": previous,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
